    {% endif %}
),
deduped AS (
    SELECT * FROM (
        SELECT *, ROW_NUMBER() OVER (PARTITION BY sale_id ORDER BY loaded_at DESC) AS row_num
        FROM source
    ) WHERE row_num = 1
)
SELECT
    sale_id,
    TRY_TO_DATE(sale_date) AS sale_date,
    customer_id,
    CAST(amount AS NUMBER(18,2)) AS amount,
    CURRENT_TIMESTAMP() AS transformed_at
FROM deduped
WHERE sale_id IS NOT NULL

