import dlt
import requests
import time
from datetime import datetime
import json

SHOPIFY_SHOP = spark.conf.get('shopify.shop_url')
SHOPIFY_TOKEN = dbutils.secrets.get(scope='shopify', key='token')

class ShopifyClient:
    def __init__(self, shop, token):
        self.shop = shop
        self.token = token
        self.base_url = f'https://{shop}/admin/api/2024-01'

    def get_orders(self, updated_at_min=None):
        params = {'limit': 250, 'status': 'any'}
        if updated_at_min:
            params['updated_at_min'] = updated_at_min

        response = requests.get(
            f'{self.base_url}/orders.json',
            headers={'X-Shopify-Access-Token': self.token},
            params=params
        )

        if response.status_code == 429:
            time.sleep(int(response.headers.get('Retry-After', 5)))
            return self.get_orders(updated_at_min)

        return response.json().get('orders', [])

@dlt.table(name='shopify_orders_bronze')
def shopify_orders_bronze():
    client = ShopifyClient(SHOPIFY_SHOP, SHOPIFY_TOKEN)
    orders = client.get_orders()
    return spark.createDataFrame([{'id': o['id'], 'raw_data': json.dumps(o)} for o in orders])

@dlt.table(name='shopify_orders_silver')
@dlt.expect_or_drop('valid_order_id', 'id IS NOT NULL')
def shopify_orders_silver():
    return dlt.read('shopify_orders_bronze').selectExpr(
        'id',
        "get_json_object(raw_data, '$.email') as customer_email",
        "CAST(get_json_object(raw_data, '$.total_price') AS DECIMAL(18,2)) as total_price"
    )

import dlt
from pyspark.sql.functions import *
from pyspark.sql.window import Window

# BRONZE LAYER - Raw Ingestion
@dlt.table(name='bronze_iot_events', table_properties={'quality': 'bronze'})
def bronze_iot_events():
    return (
        spark.readStream
        .format('kafka')
        .option('kafka.bootstrap.servers', 'kafka:9092')
        .option('subscribe', 'iot_events')
        .load()
        .selectExpr('CAST(value AS STRING) as json_data', 'timestamp as ingested_at')
    )

@dlt.table(name='bronze_sensor_readings', table_properties={'quality': 'bronze'})
def bronze_sensor_readings():
    return (
        spark.read
        .format('jdbc')
        .option('url', 'jdbc:postgresql://db:5432/sensors')
        .option('dbtable', 'sensor_readings')
        .option('user', dbutils.secrets.get('db', 'user'))
        .option('password', dbutils.secrets.get('db', 'pass'))
        .load()
        .withColumn('ingested_at', current_timestamp())
    )

# SILVER LAYER - Cleansing & Sessionization
@dlt.table(name='silver_iot_events', table_properties={'quality': 'silver'})
@dlt.expect_or_drop('valid_sensor_id', 'sensor_id IS NOT NULL')
@dlt.expect('valid_temperature', 'temperature BETWEEN -50 AND 150')
def silver_iot_events():
    return (
        dlt.read_stream('bronze_iot_events')
        .select(
            from_json(col('json_data'), 'sensor_id STRING, temperature DOUBLE, timestamp TIMESTAMP').alias('data')
        )
        .select('data.*', 'ingested_at')
        .withWatermark('timestamp', '10 minutes')
    )

@dlt.table(name='silver_sensor_sessions', table_properties={'quality': 'silver'})
def silver_sensor_sessions():
    """Sessionize sensor readings with 30-minute inactivity timeout."""
    window_spec = Window.partitionBy('sensor_id').orderBy('timestamp')

    return (
        dlt.read('silver_iot_events')
        .withColumn('time_diff', 
            unix_timestamp('timestamp') - lag(unix_timestamp('timestamp')).over(window_spec)
        )
        .withColumn('new_session', when(col('time_diff') > 1800, 1).otherwise(0))
        .withColumn('session_id', sum('new_session').over(window_spec))
        .select('sensor_id', 'session_id', 'temperature', 'timestamp')
    )

# GOLD LAYER - Aggregated Metrics
@dlt.table(name='gold_sensor_daily_metrics', table_properties={'quality': 'gold'})
def gold_sensor_daily_metrics():
    return (
        dlt.read('silver_iot_events')
        .groupBy(
            'sensor_id',
            date_trunc('day', 'timestamp').alias('day')
        )
        .agg(
            avg('temperature').alias('avg_temp'),
            min('temperature').alias('min_temp'),
            max('temperature').alias('max_temp'),
            count('*').alias('reading_count')
        )
    )

