from airflow.providers.amazon.aws.operators.emr import EmrCreateJobFlowOperator, EmrAddStepsOperator

JOB_FLOW_OVERRIDES = {
    'Name': 'fraud-detection-flink',
    'ReleaseLabel': 'emr-6.15.0',
    'Applications': [{'Name': 'Flink'}],
    'Instances': {
        'InstanceGroups': [
            {'Name': 'Master', 'Market': 'ON_DEMAND', 'InstanceRole': 'MASTER', 'InstanceType': 'm5.xlarge', 'InstanceCount': 1},
            {'Name': 'Workers', 'Market': 'SPOT', 'InstanceRole': 'CORE', 'InstanceType': 'm5.2xlarge', 'InstanceCount': 2}
        ],
        'KeepJobFlowAliveWhenNoSteps': True,
    },
}

with DAG('deploy_fraud_detection', start_date=datetime(2025, 1, 1)) as dag:
    create_cluster = EmrCreateJobFlowOperator(
        task_id='create_emr_cluster',
        job_flow_overrides=JOB_FLOW_OVERRIDES,
    )

    submit_job = EmrAddStepsOperator(
        task_id='submit_flink_job',
        job_flow_id="{{ task_instance.xcom_pull(task_ids='create_emr_cluster', key='return_value') }}",
        steps=[{
            'Name': 'Run Flink Fraud Detection',
            'ActionOnFailure': 'CONTINUE',
            'HadoopJarStep': {
                'Jar': 'command-runner.jar',
                'Args': ['flink', 'run', '-py', 's3://bucket/fraud_detection.py']
            }
        }]
    )

{
  "Comment": "Serverless data pipeline orchestration",
  "StartAt": "TriggerGlueJob",
  "States": {
    "TriggerGlueJob": {
      "Type": "Task",
      "Resource": "arn:aws:states:::glue:startJobRun.sync",
      "Parameters": {
        "JobName": "process-data-job",
        "Arguments": {
          "--s3_input_path.$": "$.input_path",
          "--s3_output_path.$": "$.output_path"
        }
      },
      "Next": "CreateAthenaTables",
      "Catch": [{
        "ErrorEquals": ["States.ALL"],
        "Next": "NotifyFailure"
      }]
    },
    "CreateAthenaTables": {
      "Type": "Task",
      "Resource": "arn:aws:states:::athena:startQueryExecution.sync",
      "Parameters": {
        "QueryString": "CREATE EXTERNAL TABLE IF NOT EXISTS my_table (id BIGINT, timestamp TIMESTAMP, value DOUBLE) PARTITIONED BY (year INT, month INT, day INT) STORED AS PARQUET LOCATION 's3://bucket/output/'",
        "WorkGroup": "primary"
      },
      "Next": "Success"
    },
    "Success": {
      "Type": "Succeed"
    },
    "NotifyFailure": {
      "Type": "Task",
      "Resource": "arn:aws:states:::sns:publish",
      "Parameters": {
        "TopicArn": "arn:aws:sns:us-east-1:123456789:pipeline-alerts",
        "Message": "Pipeline failed"
      },
      "End": true
    }
  }
}

{
  "name": "SecureSQLServerToSynapse",
  "properties": {
    "activities": [
      {
        "name": "CopyData",
        "type": "Copy",
        "inputs": [{"referenceName": "SQLServerDataset", "type": "DatasetReference"}],
        "outputs": [{"referenceName": "SynapseDataset", "type": "DatasetReference"}],
        "typeProperties": {
          "source": {
            "type": "SqlServerSource",
            "sqlReaderQuery": "SELECT employee_id, first_name, last_name, CONVERT(VARBINARY(256), salary) AS salary_encrypted, department FROM dbo.employees WHERE modified_date > '@{pipeline().parameters.watermark}'"
          },
          "sink": {
            "type": "SqlDWSink",
            "preCopyScript": "IF OBJECT_ID('dbo.employees_staging', 'U') IS NOT NULL DROP TABLE dbo.employees_staging",
            "tableOption": "autoCreate"
          },
          "enableStaging": true,
          "stagingSettings": {
            "linkedServiceName": {"referenceName": "AzureBlobStorage", "type": "LinkedServiceReference"},
            "path": "staging"
          }
        }
      },
      {
        "name": "MergeToProduction",
        "type": "SqlServerStoredProcedure",
        "dependsOn": [{"activity": "CopyData", "dependencyConditions": ["Succeeded"]}],
        "typeProperties": {
          "storedProcedureName": "[dbo].[sp_merge_employees]"
        }
      },
      {
        "name": "LogToPurview",
        "type": "WebActivity",
        "dependsOn": [{"activity": "MergeToProduction", "dependencyConditions": ["Succeeded"]}],
        "typeProperties": {
          "url": "https://purview.azure.com/api/atlas/v2/entity",
          "method": "POST",
          "authentication": {"type": "MSI"},
          "body": {
            "entity": {
              "typeName": "DataFlow",
              "attributes": {
                "name": "SQLServer_to_Synapse_Migration",
                "source": "on-prem-sqlserver",
                "sink": "synapse-dedicated-pool",
                "recordsProcessed": "@{activity('CopyData').output.rowsCopied}"
              }
            }
          }
        }
      }
    ]
  }
}
